import { useEffect, useMemo, useRef, useState, createContext, useContext, type ReactNode, type FormEvent } from 'react';
import { Route, Switch, Link, useLocation } from 'wouter';
import { motion } from 'framer-motion';
import {
  ArrowDownRight, ArrowUpRight, Banknote, BarChart3, BookOpen, Box, CalendarDays, Check, ChevronRight,
  CircleAlert, CircleDollarSign, Download, FileText, Grape, LayoutDashboard, Menu, Package,
  Pencil, Plus, Receipt, RefreshCw, Search, Settings as SettingsIcon, Sparkles,
  Trash2, TrendingUp, Upload, Wallet, X, SlidersHorizontal
} from 'lucide-react';
import { loadStore, saveStore, resetStore, unitCost, costOfRecipe, today, type Store, type Ingredient, type Product, type Recipe, type Order, type Expense, type InventoryTransaction, type BudgetAllocation } from '@/lib/store';
import '@/index.css';

const StoreContext = createContext<{ store: Store; update: (patch: Partial<Store>) => void }>({ store: loadStore(), update: () => undefined });
const useStore = () => useContext(StoreContext);
const money = (n: number) => `E${n.toLocaleString('en-SZ', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const shortDate = (s: string) => new Date(`${s}T00:00:00`).toLocaleDateString('en-SZ', { day: '2-digit', month: 'short' });
const id = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
const cx = (...v: (string | false | undefined)[]) => v.filter(Boolean).join(' ');

function Button({ children, variant = 'primary', className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'soft' | 'ghost' | 'danger' }) {
  return <button {...props} className={cx('inline-flex min-h-10 items-center justify-center gap-2 rounded-lg px-3.5 text-sm font-semibold', variant === 'primary' && 'bg-primary text-primary-foreground hover:opacity-90', variant === 'soft' && 'bg-secondary text-secondary-foreground hover:brightness-95', variant === 'ghost' && 'text-muted-foreground hover:bg-muted hover:text-foreground', variant === 'danger' && 'bg-destructive text-destructive-foreground hover:opacity-90', className)} />;
}
function IconButton({ label, children, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { label: string }) {
  return <button aria-label={label} title={label} {...props} className={cx('inline-flex h-9 w-9 items-center justify-center rounded-lg text-muted-foreground hover:bg-muted hover:text-foreground', props.className)}>{children}</button>;
}
function Card({ children, className = '' }: { children: ReactNode; className?: string }) {
  return <section className={cx('rounded-xl border bg-card text-card-foreground shadow-sm', className)}>{children}</section>;
}
function Modal({ title, subtitle, onClose, children, wide = false }: { title: string; subtitle?: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-foreground/35 p-0 backdrop-blur-[2px] sm:items-center sm:p-6" role="presentation" onMouseDown={e => e.target === e.currentTarget && onClose()}>
    <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} className={cx('max-h-[92dvh] w-full overflow-auto rounded-t-2xl border bg-card p-5 shadow-2xl sm:rounded-2xl', wide ? 'max-w-3xl' : 'max-w-xl')}>
      <div className="mb-5 flex items-start justify-between gap-4"><div><h2 className="display text-2xl font-semibold">{title}</h2>{subtitle && <p className="mt-1 text-sm text-muted-foreground">{subtitle}</p>}</div><IconButton label="Close dialog" onClick={onClose}><X size={18} /></IconButton></div>
      {children}
    </motion.div>
  </div>;
}
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="block space-y-1.5 text-sm font-medium"><span>{label}</span>{children}{hint && <span className="block text-xs font-normal text-muted-foreground">{hint}</span>}</label>;
}
function Input({ className = '', ...props }: React.InputHTMLAttributes<HTMLInputElement>) {
  return <input {...props} className={cx('h-10 w-full rounded-lg border bg-background px-3 text-sm outline-none placeholder:text-muted-foreground/65 focus:border-primary focus:ring-2 focus:ring-primary/15', className)} />;
}
function Select({ className = '', ...props }: React.SelectHTMLAttributes<HTMLSelectElement>) {
  return <select {...props} className={cx('h-10 w-full rounded-lg border bg-background px-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15', className)} />;
}
function Empty({ icon: Icon = Sparkles, title, detail, action }: { icon?: typeof Sparkles; title: string; detail: string; action?: ReactNode }) {
  return <div className="flex min-h-48 flex-col items-center justify-center px-6 py-10 text-center"><span className="mb-3 rounded-full bg-secondary p-3 text-secondary-foreground"><Icon size={22} /></span><h3 className="font-semibold">{title}</h3><p className="mt-1 max-w-sm text-sm text-muted-foreground">{detail}</p>{action && <div className="mt-4">{action}</div>}</div>;
}
function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="mono mb-2 text-[10px] font-semibold uppercase tracking-[.18em] text-primary">{eyebrow}</p><h1 className="display text-3xl font-semibold tracking-tight sm:text-[2.45rem]">{title}</h1><p className="mt-1 text-sm text-muted-foreground">{description}</p></div>{action}</div>;
}
function AppShell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [open, setOpen] = useState(false);
  const nav = [
    { href: '/', label: 'Overview', icon: LayoutDashboard },
    { href: '/orders', label: 'Orders', icon: Receipt },
    { href: '/products', label: 'Products', icon: Package },
    { href: '/recipes', label: 'Recipes', icon: BookOpen },
    { href: '/ingredients', label: 'Ingredients', icon: Grape },
    { href: '/inventory', label: 'Inventory', icon: Box },
    { href: '/expenses', label: 'Expenses', icon: Wallet },
    { href: '/reports', label: 'Reports', icon: BarChart3 },
    { href: '/budget', label: 'Budget', icon: CircleDollarSign },
  ];
  const { store } = useStore();
  return <div className="min-h-[100dvh] bg-background">
    <aside className={cx('fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col bg-sidebar text-sidebar-foreground transition-transform duration-300 lg:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}>
      <div className="flex items-center gap-3 border-b border-sidebar-border px-5 py-5"><img src="/little-bliss-logo.jpg" alt="Little Bliss Bakery logo" className="h-11 w-11 rounded-full object-cover ring-2 ring-secondary/60" /><div><p className="display text-lg leading-tight">Little Bliss</p><p className="text-[10px] uppercase tracking-[.22em] text-sidebar-foreground/60">Bakery desk</p></div><IconButton label="Close menu" className="ml-auto text-sidebar-foreground lg:hidden" onClick={() => setOpen(false)}><X size={17} /></IconButton></div>
      <div className="px-4 pb-3 pt-5"><div className="rounded-lg bg-sidebar-accent p-3"><p className="text-[11px] text-sidebar-foreground/60">Good morning, baker</p><p className="mt-1 text-sm font-semibold">{new Date().toLocaleDateString('en-SZ', { weekday: 'long', day: 'numeric', month: 'long' })}</p><div className="mt-3 flex items-center gap-2 text-xs text-secondary"><span className="h-1.5 w-1.5 rounded-full bg-secondary" /> Saved on this device</div></div></div>
      <nav className="flex-1 space-y-0.5 overflow-y-auto px-3 py-2">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase()}`} onClick={() => setOpen(false)} className={cx('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium', location === href ? 'bg-sidebar-primary text-sidebar-primary-foreground' : 'text-sidebar-foreground/72 hover:bg-sidebar-accent hover:text-sidebar-foreground')}><Icon size={17} strokeWidth={1.8} /><span>{label}</span>{href === '/ingredients' && store.ingredients.some(i => i.purchasePrice === 0) && <span className="ml-auto h-2 w-2 rounded-full bg-accent" />}</Link>)}</nav>
      <div className="border-t border-sidebar-border p-3"><Link href="/settings" data-testid="link-nav-settings" onClick={() => setOpen(false)} className={cx('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium', location === '/settings' ? 'bg-sidebar-primary text-sidebar-primary-foreground' : 'text-sidebar-foreground/72 hover:bg-sidebar-accent hover:text-sidebar-foreground')}><SettingsIcon size={17} /><span>Settings</span></Link><p className="px-3 pb-1 pt-4 text-[10px] uppercase tracking-wider text-sidebar-foreground/40">Little Bliss · v1.0</p></div>
    </aside>
    <div className="lg:pl-[248px]"><header className="sticky top-0 z-30 flex h-[68px] items-center justify-between border-b bg-background/90 px-4 backdrop-blur-md sm:px-7"><div className="flex items-center gap-3"><IconButton label="Open menu" className="lg:hidden" onClick={() => setOpen(true)}><Menu size={20} /></IconButton><div className="hidden items-center gap-2 text-sm text-muted-foreground sm:flex"><span>Little Bliss Bakery</span><ChevronRight size={14} /><span className="font-semibold text-foreground">{location === '/' ? 'Overview' : location.slice(1).replace('-', ' ')}</span></div></div><div className="flex items-center gap-2"><span className="hidden items-center gap-2 rounded-full bg-secondary/60 px-3 py-1.5 text-xs font-medium text-secondary-foreground sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-primary" /> Local data</span><Link href="/settings" data-testid="link-header-settings" className="rounded-full border p-2 text-muted-foreground hover:bg-muted"><SettingsIcon size={17} /></Link></div></header><main className="page-enter mx-auto max-w-[1480px] p-4 sm:p-7">{children}</main></div>
  </div>;
}

function Dashboard() {
  const { store } = useStore();
  const revenue = store.orders.reduce((s, o) => s + o.items.reduce((a, i) => a + i.quantity * i.unitPrice, 0) - o.discount + o.deliveryFee, 0);
  const received = store.orders.reduce((s, o) => s + o.amountPaid, 0);
  const expenses = store.expenses.reduce((s, e) => s + e.amount, 0);
  const low = store.ingredients.filter(i => i.minimumStock > 0 && i.currentStock <= i.minimumStock);
  const outstanding = revenue - received;
  const costs = store.orders.reduce((s, o) => s + o.items.reduce((a, i) => a + i.quantity * i.costSnapshot, 0), 0);
  return <div className="stagger">
    <PageHeader eyebrow="Tuesday · 06 August 2024" title="Good morning, baker." description="Your quiet view of what needs care today." action={<Link href="/orders?new=1" data-testid="link-quick-new-order"><Button><Plus size={17} /> New order</Button></Link>} />
    <Card className="relative mb-5 h-[124px] overflow-hidden border-0 bg-sidebar text-sidebar-foreground"><img src="/little-bliss-cover.png" alt="Little Bliss Bakery treats on a wooden counter" className="absolute inset-0 h-full w-full object-cover object-center opacity-55" /><div className="absolute inset-0 bg-gradient-to-r from-sidebar via-sidebar/80 to-transparent" /><div className="relative flex h-full max-w-md flex-col justify-center px-6"><p className="mono text-[10px] uppercase tracking-[.22em] text-secondary">Little Bliss Bakery</p><p className="display mt-1 text-2xl font-semibold">A taste of pure bliss.</p><p className="mt-1 text-xs text-sidebar-foreground/70">Your shelves, orders, and numbers — in one calm view.</p></div></Card>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <Metric label="Revenue this month" value={money(revenue)} trend="+12.4%" icon={TrendingUp} tone="primary" note="from 11 orders" />
      <Metric label="Received" value={money(received)} trend={outstanding ? `${money(outstanding)} due` : 'All settled'} icon={Banknote} tone="lime" note="customer payments" />
      <Metric label="Expenses" value={money(expenses)} trend="this month" icon={ArrowDownRight} tone="peach" note="recorded costs" />
      <Metric label="Expected profit" value={money(revenue - costs - expenses)} trend={revenue ? `${Math.round(((revenue - costs - expenses) / revenue) * 100)}% margin` : '—'} icon={Sparkles} tone="dark" note="after estimated costs" />
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.45fr_1fr]">
      <Card className="overflow-hidden"><div className="flex items-center justify-between border-b px-5 py-4"><div><h2 className="font-semibold">Today at a glance</h2><p className="mt-0.5 text-xs text-muted-foreground">The orders that shape your bake list.</p></div><Link href="/orders" className="text-xs font-semibold text-primary hover:underline">View all orders <ChevronRight className="inline" size={14} /></Link></div><div className="grid grid-cols-2 divide-x border-b"><div className="p-5"><p className="text-xs text-muted-foreground">Orders due today</p><p className="mono mt-2 text-3xl font-semibold">{store.orders.filter(o => o.dueDate === today()).length.toString().padStart(2, '0')}</p><p className="mt-1 text-xs text-muted-foreground">ready for the oven</p></div><div className="p-5"><p className="text-xs text-muted-foreground">Outstanding</p><p className="mono mt-2 text-3xl font-semibold text-primary">{money(outstanding)}</p><p className="mt-1 text-xs text-muted-foreground">across {store.orders.filter(o => o.amountPaid < (o.items.reduce((a, i) => a + i.quantity * i.unitPrice, 0) - o.discount + o.deliveryFee)).length} orders</p></div></div><div className="divide-y">{store.orders.slice(0, 4).map(o => <OrderRow key={o.id} order={o} store={store} />)}</div>{!store.orders.length && <Empty icon={Receipt} title="No orders on the board" detail="New orders will appear here when your day starts." action={<Link href="/orders"><Button>Make an order</Button></Link>} />}</Card>
      <Card><div className="flex items-center justify-between border-b px-5 py-4"><div><h2 className="font-semibold">Attention shelf</h2><p className="mt-0.5 text-xs text-muted-foreground">Small things worth noticing.</p></div><span className="rounded-full bg-accent/35 px-2 py-1 text-xs font-semibold">{low.length} low</span></div><div className="p-5">{low.length ? <div className="space-y-4">{low.slice(0, 5).map(i => <div key={i.id} className="flex items-center justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><span className="rounded-lg bg-accent/30 p-2 text-primary"><Grape size={16} /></span><div className="min-w-0"><p className="truncate text-sm font-semibold">{i.name}</p><p className="text-xs text-muted-foreground">{i.currentStock.toLocaleString()} {i.unit} left</p></div></div><span className="text-xs font-medium text-primary">min {i.minimumStock}</span></div>)}</div> : <Empty icon={Check} title="Stock looks steady" detail="No ingredients are below their minimum level." />}<Link href="/inventory" className="mt-5 flex items-center justify-center gap-1 rounded-lg border py-2.5 text-xs font-semibold text-primary hover:bg-muted">Open inventory <ChevronRight size={14} /></Link></div></Card>
    </div>
    <div className="mt-5 grid gap-5 lg:grid-cols-[1fr_1fr_1fr]"><Card className="p-5"><div className="mb-5 flex items-center gap-3"><span className="rounded-lg bg-secondary p-2"><Wallet size={17} /></span><div><h2 className="font-semibold">Cash pulse</h2><p className="text-xs text-muted-foreground">Received vs recorded outflow</p></div></div><div className="flex items-end gap-4"><p className="mono text-3xl font-semibold">{money(received - expenses)}</p><span className={cx('mb-1 text-xs font-semibold', received >= expenses ? 'text-primary' : 'text-destructive')}>{received >= expenses ? 'positive' : 'watch this'}</span></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(100, received ? expenses / received * 100 : 0)}%` }} /></div><div className="mt-2 flex justify-between text-xs text-muted-foreground"><span>expenses {money(expenses)}</span><span>received {money(received)}</span></div></Card><Card className="p-5"><div className="mb-4 flex items-center gap-3"><span className="rounded-lg bg-accent/35 p-2"><CalendarDays size={17} /></span><div><h2 className="font-semibold">Quick actions</h2><p className="text-xs text-muted-foreground">Keep the desk moving.</p></div></div><div className="grid grid-cols-2 gap-2"><Quick href="/orders?new=1" icon={Receipt} label="Record order" /><Quick href="/expenses?new=1" icon={Wallet} label="Add expense" /><Quick href="/inventory?new=1" icon={Box} label="Adjust stock" /><Quick href="/reports" icon={BarChart3} label="See reports" /></div></Card><Card className="p-5"><div className="mb-4 flex items-center gap-3"><span className="rounded-lg bg-primary/10 p-2 text-primary"><TrendingUp size={17} /></span><div><h2 className="font-semibold">Top bake</h2><p className="text-xs text-muted-foreground">By sales value this month</p></div></div>{store.products.slice(0, 3).map((p, i) => <div key={p.id} className="mb-3 flex items-center gap-3 last:mb-0"><span className="mono w-4 text-xs text-muted-foreground">0{i + 1}</span><div className="min-w-0 flex-1"><div className="flex justify-between text-sm"><span className="truncate font-medium">{p.name}</span><span className="mono ml-2 text-xs">{money(p.retailPriceDozen)}</span></div><div className="mt-1.5 h-1 rounded-full bg-muted"><div className="h-full rounded-full bg-secondary" style={{ width: `${100 - i * 18}%` }} /></div></div></div>)}</Card></div>
  </div>;
}
function Metric({ label, value, trend, note, icon: Icon, tone }: { label: string; value: string; trend: string; note: string; icon: typeof TrendingUp; tone: string }) {
  const bg = tone === 'primary' ? 'bg-primary text-primary-foreground' : tone === 'lime' ? 'bg-secondary text-secondary-foreground' : tone === 'peach' ? 'bg-accent/45' : 'bg-sidebar text-sidebar-foreground';
  return <Card className={cx('relative overflow-hidden border-0 p-5', bg)}><div className="flex items-start justify-between"><div><p className="text-xs opacity-70">{label}</p><p className="mono mt-3 text-[1.7rem] font-semibold tracking-tight">{value}</p></div><Icon size={20} className="opacity-70" /></div><div className="mt-4 flex items-center justify-between text-xs"><span className="font-semibold">{trend}</span><span className="opacity-65">{note}</span></div></Card>;
}
function Quick({ href, icon: Icon, label }: { href: string; icon: typeof Receipt; label: string }) { return <Link href={href} className="flex items-center gap-2 rounded-lg border px-3 py-2.5 text-xs font-semibold hover:border-primary hover:bg-primary/5"><Icon size={15} className="text-primary" />{label}</Link>; }
function OrderRow({ order, store }: { order: Order; store: Store }) {
  const total = order.items.reduce((a, i) => a + i.quantity * i.unitPrice, 0) - order.discount + order.deliveryFee;
  return <div className="flex items-center justify-between gap-3 px-5 py-4"><div className="flex min-w-0 items-center gap-3"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-secondary text-xs font-bold text-secondary-foreground">{order.customerName.split(' ').map(x => x[0]).join('').slice(0, 2)}</span><div className="min-w-0"><p className="truncate text-sm font-semibold">{order.customerName}</p><p className="text-xs text-muted-foreground">{order.orderNumber} · {order.items.map(i => `${i.quantity} × ${store.products.find(p => p.id === i.productId)?.name}`).join(', ')}</p></div></div><div className="text-right"><p className="mono text-sm font-semibold">{money(total)}</p><Status status={order.paymentStatus} /></div></div>;
}
function Status({ status }: { status: string }) { return <span className={cx('mt-1 inline-flex rounded-full px-2 py-0.5 text-[10px] font-semibold', status === 'Paid' ? 'bg-secondary text-secondary-foreground' : status === 'Part paid' ? 'bg-accent/50 text-foreground' : 'bg-muted text-muted-foreground')}>{status}</span>; }

function Products() {
  const { store, update } = useStore(); const [edit, setEdit] = useState<Product | null>(null); const [search, setSearch] = useState('');
  const rows = store.products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));
  const cost = (p: Product) => { const r = store.recipes.find(x => x.productId === p.id); return r ? costOfRecipe(r, store.ingredients) * (p.batchYield / r.batchYield) + p.laborCost + p.energyCost + p.packagingCost : 0; };
  return <div><PageHeader eyebrow="Catalog" title="Products" description="Your menu, priced with the real cost of making it." action={<Button data-testid="button-add-product" onClick={() => setEdit({ id: id('prod'), name: '', category: 'Cookies', description: '', image: '', batchYield: 12, servingSize: '1 dozen', laborCost: 0, energyCost: 0, packagingCost: 0, wastagePercent: 0, retailPriceDozen: 0, wholesalePriceDozen: 0, active: true })}><Plus size={17} /> Add product</Button>} /><div className="mb-4 flex items-center gap-3"><div className="relative max-w-sm flex-1"><Search className="absolute left-3 top-3 text-muted-foreground" size={16} /><Input data-testid="input-search-products" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search products..." className="pl-9" /></div><Button variant="ghost" className="hidden sm:inline-flex"><SlidersHorizontal size={16} /> Filter</Button></div><Card className="overflow-hidden">{rows.length ? <div className="overflow-x-auto"><table className="w-full min-w-[740px] text-left text-sm"><thead className="bg-muted/55 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3.5">Product</th><th>Retail / dozen</th><th>Cost to make</th><th>Profit</th><th>Margin</th><th>Active</th><th className="pr-5 text-right"> </th></tr></thead><tbody className="divide-y">{rows.map(p => { const c = cost(p); const profit = p.retailPriceDozen - c; return <tr key={p.id} data-testid={`row-product-${p.id}`} className="hover:bg-muted/25"><td className="px-5 py-4"><p className="font-semibold">{p.name}</p><p className="mt-0.5 text-xs text-muted-foreground">{p.category} · yield {p.batchYield}</p></td><td className="mono">{money(p.retailPriceDozen)}</td><td className={c ? 'mono' : 'text-xs text-muted-foreground'}>{c ? money(c) : 'Cost requires ingredient pricing'}</td><td className="mono text-primary">{c ? money(profit) : '—'}</td><td>{c ? <span className="rounded-full bg-secondary px-2 py-1 text-xs font-semibold">{Math.round(profit / p.retailPriceDozen * 100)}%</span> : '—'}</td><td><button data-testid={`button-toggle-product-${p.id}`} onClick={() => update({ products: store.products.map(x => x.id === p.id ? { ...x, active: !x.active } : x) })} className={cx('h-5 w-9 rounded-full p-0.5', p.active ? 'bg-primary' : 'bg-muted')}><span className={cx('block h-4 w-4 rounded-full bg-card transition-transform', p.active && 'translate-x-4')} /></button></td><td className="pr-5 text-right"><IconButton label={`Edit ${p.name}`} data-testid={`button-edit-product-${p.id}`} onClick={() => setEdit(p)}><Pencil size={16} /></IconButton></td></tr>; })}</tbody></table></div> : <Empty icon={Package} title="No products found" detail="Add a product to start tracking its price and margin." />}</Card>{edit && <ProductModal value={edit} onClose={() => setEdit(null)} onSave={p => { const exists = store.products.some(x => x.id === p.id); update({ products: exists ? store.products.map(x => x.id === p.id ? p : x) : [...store.products, p] }); setEdit(null); }} />}</div>;
}
function ProductModal({ value, onClose, onSave }: { value: Product; onClose: () => void; onSave: (v: Product) => void }) {
  const [p, setP] = useState(value); const set = (k: keyof Product, v: string | number | boolean) => setP(x => ({ ...x, [k]: v }));
  return <Modal title={value.name ? 'Edit product' : 'New product'} subtitle="Keep the shelf price connected to the work behind it." onClose={onClose}><form onSubmit={e => { e.preventDefault(); onSave(p); }} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Product name"><Input required data-testid="input-product-name" value={p.name} onChange={e => set('name', e.target.value)} /></Field><Field label="Category"><Input value={p.category} onChange={e => set('category', e.target.value)} /></Field><Field label="Retail price / dozen"><Input required type="number" min="0" step=".01" value={p.retailPriceDozen} onChange={e => set('retailPriceDozen', Number(e.target.value))} /></Field><Field label="Wholesale price / dozen"><Input type="number" min="0" step=".01" value={p.wholesalePriceDozen} onChange={e => set('wholesalePriceDozen', Number(e.target.value))} /></Field><Field label="Batch yield"><Input type="number" min="1" value={p.batchYield} onChange={e => set('batchYield', Number(e.target.value))} /></Field><Field label="Serving size"><Input value={p.servingSize} onChange={e => set('servingSize', e.target.value)} /></Field><Field label="Labour cost / batch"><Input type="number" min="0" step=".01" value={p.laborCost} onChange={e => set('laborCost', Number(e.target.value))} /></Field><Field label="Energy cost / batch"><Input type="number" min="0" step=".01" value={p.energyCost} onChange={e => set('energyCost', Number(e.target.value))} /></Field><Field label="Packaging cost / batch"><Input type="number" min="0" step=".01" value={p.packagingCost} onChange={e => set('packagingCost', Number(e.target.value))} /></Field><Field label="Wastage %"><Input type="number" min="0" step=".1" value={p.wastagePercent} onChange={e => set('wastagePercent', Number(e.target.value))} /></Field></div><Field label="Description"><textarea className="min-h-20 w-full rounded-lg border bg-background p-3 text-sm outline-none focus:border-primary" value={p.description} onChange={e => set('description', e.target.value)} /></Field><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit" data-testid="button-save-product"><Check size={16} /> Save product</Button></div></form></Modal>;
}

function Ingredients() {
  const { store, update } = useStore(); const [edit, setEdit] = useState<Ingredient | null>(null); const [search, setSearch] = useState('');
  const rows = store.ingredients.filter(i => i.name.toLowerCase().includes(search.toLowerCase()));
  return <div><PageHeader eyebrow="Pantry" title="Ingredients" description="One honest place for every pack, price, and supplier." action={<Button data-testid="button-add-ingredient" onClick={() => setEdit({ id: id('ing'), name: '', category: 'Dry goods', supplier: '', packSize: 0, unit: 'g', purchasePrice: 0, purchaseDate: today(), notes: '', currentStock: 0, minimumStock: 0, priceHistory: [] })}><Plus size={17} /> Add ingredient</Button>} /><div className="mb-4 flex items-center gap-3"><div className="relative max-w-sm flex-1"><Search className="absolute left-3 top-3 text-muted-foreground" size={16} /><Input data-testid="input-search-ingredients" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search ingredients..." className="pl-9" /></div><span className="text-xs text-muted-foreground">{store.ingredients.filter(i => !i.purchasePrice).length} still need pricing</span></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left text-sm"><thead className="bg-muted/55 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3.5">Ingredient</th><th>Pack</th><th>Purchase price</th><th>Unit cost</th><th>Supplier</th><th>Stock</th><th className="pr-5 text-right"> </th></tr></thead><tbody className="divide-y">{rows.map(i => { const uc = unitCost(i); const low = i.minimumStock > 0 && i.currentStock <= i.minimumStock; return <tr key={i.id} className="hover:bg-muted/25"><td className="px-5 py-4"><p className="font-semibold">{i.name}</p><p className="text-xs text-muted-foreground">{i.category}</p></td><td className="mono">{i.packSize ? `${i.packSize.toLocaleString()} ${i.unit}` : 'Not set'}</td><td className={i.purchasePrice ? 'mono' : 'text-xs font-semibold text-accent-foreground'}>{i.purchasePrice ? money(i.purchasePrice) : 'Price missing'}</td><td className="mono text-muted-foreground">{uc ? `${money(uc)} / ${i.unit}` : '—'}</td><td>{i.supplier || <span className="text-muted-foreground">—</span>}</td><td><span className={cx('mono text-xs', low && 'font-semibold text-destructive')}>{i.currentStock.toLocaleString()} {i.unit}</span>{low && <CircleAlert size={13} className="ml-1 inline text-destructive" />}</td><td className="pr-5 text-right"><IconButton label={`Edit ${i.name}`} data-testid={`button-edit-ingredient-${i.id}`} onClick={() => setEdit(i)}><Pencil size={16} /></IconButton></td></tr>; })}</tbody></table></div></Card>{edit && <IngredientModal value={edit} onClose={() => setEdit(null)} onSave={i => { const exists = store.ingredients.some(x => x.id === i.id); update({ ingredients: exists ? store.ingredients.map(x => x.id === i.id ? i : x) : [...store.ingredients, i] }); setEdit(null); }} />}</div>;
}
function IngredientModal({ value, onClose, onSave }: { value: Ingredient; onClose: () => void; onSave: (v: Ingredient) => void }) {
  const [i, setI] = useState(value); const set = (k: keyof Ingredient, v: string | number) => setI(x => ({ ...x, [k]: v }));
  return <Modal title={value.name ? 'Edit ingredient' : 'New ingredient'} subtitle="Prices are local, editable, and never hidden behind a sync." onClose={onClose}><form onSubmit={e => { e.preventDefault(); onSave(i); }} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Ingredient name"><Input required value={i.name} onChange={e => set('name', e.target.value)} /></Field><Field label="Category"><Input value={i.category} onChange={e => set('category', e.target.value)} /></Field><Field label="Pack size"><Input type="number" min="0" step=".01" value={i.packSize} onChange={e => set('packSize', Number(e.target.value))} /></Field><Field label="Unit"><Select value={i.unit} onChange={e => set('unit', e.target.value)}><option value="g">grams (g)</option><option value="ml">millilitres (ml)</option><option value="each">each</option></Select></Field><Field label="Purchase price" hint={!i.purchasePrice ? 'Leave 0 until you have the receipt.' : undefined}><Input type="number" min="0" step=".01" value={i.purchasePrice} onChange={e => set('purchasePrice', Number(e.target.value))} /></Field><Field label="Supplier"><Input value={i.supplier} onChange={e => set('supplier', e.target.value)} /></Field><Field label="Current stock"><Input type="number" min="0" step=".01" value={i.currentStock} onChange={e => set('currentStock', Number(e.target.value))} /></Field><Field label="Minimum stock"><Input type="number" min="0" step=".01" value={i.minimumStock} onChange={e => set('minimumStock', Number(e.target.value))} /></Field></div><Field label="Notes"><textarea className="min-h-20 w-full rounded-lg border bg-background p-3 text-sm outline-none focus:border-primary" value={i.notes} onChange={e => set('notes', e.target.value)} /></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Save ingredient</Button></div></form></Modal>;
}

function Recipes() {
  const { store, update } = useStore(); const [selected, setSelected] = useState<Recipe | null>(null);
  const save = (r: Recipe) => { update({ recipes: store.recipes.map(x => x.id === r.id ? r : x) }); setSelected(null); };
  return <div><PageHeader eyebrow="Bake book" title="Recipes" description="Build batches with costs that update as your pantry prices change." action={<span className="rounded-full bg-secondary px-3 py-2 text-xs font-semibold text-secondary-foreground">{store.recipes.length} recipes</span>} /><div className="grid gap-4 lg:grid-cols-3">{store.recipes.map(r => { const p = store.products.find(x => x.id === r.productId); const missing = r.ingredients.filter(row => { const i = store.ingredients.find(x => x.id === row.ingredientId); return !i || !unitCost(i); }).length; const c = costOfRecipe(r, store.ingredients); return <Card key={r.id} className="flex flex-col overflow-hidden"><div className="flex items-start justify-between bg-sidebar p-5 text-sidebar-foreground"><div><p className="mono text-[10px] uppercase tracking-wider text-sidebar-foreground/60">Recipe {r.id.replace('recipe-', '').toUpperCase()}</p><h2 className="display mt-2 text-xl font-semibold">{p?.name}</h2></div><span className="rounded-full bg-sidebar-primary px-2 py-1 text-[10px] font-semibold text-sidebar-primary-foreground">yield {r.batchYield}</span></div><div className="flex-1 p-5"><div className="mb-4 flex items-center justify-between border-b pb-3"><span className="text-xs text-muted-foreground">Estimated batch cost</span><span className={cx('mono font-semibold', missing > 0 && 'text-muted-foreground')}>{missing ? 'Cost requires ingredient pricing' : money(c)}</span></div><div className="space-y-2">{r.ingredients.slice(0, 5).map(row => <div key={row.ingredientId} className="flex justify-between text-sm"><span className="text-muted-foreground">{store.ingredients.find(i => i.id === row.ingredientId)?.name || 'Unknown ingredient'}</span><span className="mono text-xs">{row.quantity}{row.unit}</span></div>)}{r.ingredients.length > 5 && <p className="pt-1 text-xs text-primary">+ {r.ingredients.length - 5} more ingredients</p>}</div></div><div className="flex items-center justify-between border-t bg-muted/25 px-5 py-3"><span className={cx('text-xs font-semibold', missing > 0 ? 'text-accent-foreground' : 'text-primary')}>{missing ? `${missing} price${missing > 1 ? 's' : ''} missing` : `${money(c / r.batchYield)} per piece`}</span><Button variant="ghost" data-testid={`button-edit-recipe-${r.id}`} onClick={() => setSelected(r)}><Pencil size={15} /> Edit recipe</Button></div></Card>; })}</div>{selected && <RecipeModal value={selected} ingredients={store.ingredients} onClose={() => setSelected(null)} onSave={save} />}</div>;
}
function RecipeModal({ value, ingredients, onClose, onSave }: { value: Recipe; ingredients: Ingredient[]; onClose: () => void; onSave: (v: Recipe) => void }) {
  const [r, setR] = useState(value); const updateRow = (index: number, key: string, val: string | number) => setR(x => ({ ...x, ingredients: x.ingredients.map((row, i) => i === index ? { ...row, [key]: val } : row) }));
  return <Modal title="Edit recipe" subtitle="Quantities are for one batch." onClose={onClose} wide><form onSubmit={e => { e.preventDefault(); onSave(r); }}><div className="mb-5 grid gap-4 sm:grid-cols-3"><Field label="Batch yield"><Input type="number" value={r.batchYield} onChange={e => setR({ ...r, batchYield: Number(e.target.value) })} /></Field><Field label="Dough weight (g)"><Input type="number" value={r.doughWeight} onChange={e => setR({ ...r, doughWeight: Number(e.target.value) })} /></Field><Field label="Finished weight (g)"><Input type="number" value={r.finishedWeight} onChange={e => setR({ ...r, finishedWeight: Number(e.target.value) })} /></Field></div><div className="overflow-x-auto rounded-lg border"><table className="w-full min-w-[560px] text-left text-sm"><thead className="bg-muted text-xs text-muted-foreground"><tr><th className="px-3 py-2">Ingredient</th><th>Quantity</th><th>Unit</th><th>Cost</th><th /></tr></thead><tbody className="divide-y">{r.ingredients.map((row, index) => { const ing = ingredients.find(i => i.id === row.ingredientId); const c = ing && unitCost(ing) ? unitCost(ing)! * row.quantity : 0; return <tr key={`${row.ingredientId}-${index}`}><td className="px-3 py-2"><Select value={row.ingredientId} onChange={e => updateRow(index, 'ingredientId', e.target.value)}>{ingredients.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}</Select></td><td className="w-24"><Input type="number" value={row.quantity} onChange={e => updateRow(index, 'quantity', Number(e.target.value))} /></td><td className="w-24"><Input value={row.unit} onChange={e => updateRow(index, 'unit', e.target.value)} /></td><td className="mono text-xs">{c ? money(c) : '—'}</td><td className="w-12"><IconButton label="Remove ingredient" onClick={() => setR(x => ({ ...x, ingredients: x.ingredients.filter((_, i) => i !== index) }))}><Trash2 size={15} /></IconButton></td></tr>; })}</tbody></table></div><Button type="button" variant="soft" className="mt-3" onClick={() => setR(x => ({ ...x, ingredients: [...x.ingredients, { ingredientId: ingredients[0]?.id || '', quantity: 0, unit: 'g', notes: '' }] }))}><Plus size={15} /> Add ingredient</Button><div className="mt-5 flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Save recipe</Button></div></form></Modal>;
}

function Orders() {
  const { store, update } = useStore(); const [edit, setEdit] = useState<Order | null>(null); const [search, setSearch] = useState(''); const [location] = useLocation();
  const rows = store.orders.filter(o => `${o.customerName} ${o.orderNumber}`.toLowerCase().includes(search.toLowerCase()));
  const newOrder = () => setEdit({ id: id('order'), orderNumber: `LB-${1043 + store.orders.length}`, customerName: '', phone: '', orderDate: today(), dueDate: today(), items: [{ productId: store.products[0]?.id || '', quantity: 1, unitPrice: store.products[0]?.retailPriceDozen || 0, costSnapshot: 0 }], discount: 0, deliveryFee: 0, paymentStatus: 'Unpaid', paymentMethod: 'Cash', amountPaid: 0, payments: [], notes: '', createdAt: new Date().toISOString() });
  useEffect(() => { if (location.includes('?new=1')) newOrder(); }, [location]);
  return <div><PageHeader eyebrow="Sales desk" title="Orders" description="A clear queue from first message to paid-in-full." action={<Button data-testid="button-add-order" onClick={newOrder}><Plus size={17} /> New order</Button>} /><div className="mb-4 flex items-center gap-3"><div className="relative max-w-sm flex-1"><Search className="absolute left-3 top-3 text-muted-foreground" size={16} /><Input data-testid="input-search-orders" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search customer or order no." className="pl-9" /></div><span className="hidden text-xs text-muted-foreground sm:block">{rows.length} visible orders</span></div><Card className="overflow-hidden">{rows.length ? <div className="overflow-x-auto"><table className="w-full min-w-[830px] text-left text-sm"><thead className="bg-muted/55 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3.5">Order</th><th>Due</th><th>Total</th><th>Paid</th><th>Outstanding</th><th>Status</th><th className="pr-5 text-right"> </th></tr></thead><tbody className="divide-y">{rows.map(o => { const total = o.items.reduce((a, i) => a + i.quantity * i.unitPrice, 0) - o.discount + o.deliveryFee; return <tr key={o.id} className="hover:bg-muted/25"><td className="px-5 py-4"><p className="font-semibold">{o.orderNumber}</p><p className="text-xs text-muted-foreground">{o.customerName} · {o.phone || 'no phone'}</p></td><td><span className={cx(o.dueDate < today() && o.paymentStatus !== 'Paid' && 'text-destructive')}>{shortDate(o.dueDate)}</span></td><td className="mono">{money(total)}</td><td className="mono">{money(o.amountPaid)}</td><td className="mono text-primary">{money(Math.max(0, total - o.amountPaid))}</td><td><Status status={o.paymentStatus} /></td><td className="pr-5 text-right"><IconButton label={`Edit ${o.orderNumber}`} onClick={() => setEdit(o)}><Pencil size={16} /></IconButton></td></tr>; })}</tbody></table></div> : <Empty icon={Receipt} title="Your order board is clear" detail="Record your first customer order and it will stay here offline." action={<Button onClick={newOrder}><Plus size={16} /> Add order</Button>} />}</Card>{edit && <OrderModal value={edit} store={store} onClose={() => setEdit(null)} onSave={o => { const exists = store.orders.some(x => x.id === o.id); update({ orders: exists ? store.orders.map(x => x.id === o.id ? o : x) : [o, ...store.orders] }); setEdit(null); }} />}</div>;
}
function OrderModal({ value, store, onClose, onSave }: { value: Order; store: Store; onClose: () => void; onSave: (v: Order) => void }) {
  const [o, setO] = useState(value); const total = o.items.reduce((a, i) => a + i.quantity * i.unitPrice, 0) - o.discount + o.deliveryFee; const set = (k: keyof Order, v: string | number) => setO(x => ({ ...x, [k]: v }));
  const snapshot = (item: Order['items'][number]) => { const p = store.products.find(x => x.id === item.productId); const r = store.recipes.find(x => x.productId === item.productId); return r && p ? costOfRecipe(r, store.ingredients) * (p.batchYield / r.batchYield) : item.costSnapshot; };
  const updateItem = (idx: number, key: string, val: string | number) => setO(x => ({ ...x, items: x.items.map((row, i) => i === idx ? { ...row, [key]: val } : row) }));
  return <Modal title={value.customerName ? `Edit ${value.orderNumber}` : 'New customer order'} subtitle="Save a price snapshot so this order stays historically accurate." onClose={onClose} wide><form onSubmit={e => { e.preventDefault(); onSave({ ...o, items: o.items.map(item => ({ ...item, costSnapshot: snapshot(item) })) }); }}><div className="grid gap-4 sm:grid-cols-3"><Field label="Customer name"><Input required value={o.customerName} onChange={e => set('customerName', e.target.value)} /></Field><Field label="Phone"><Input value={o.phone} onChange={e => set('phone', e.target.value)} /></Field><Field label="Order number"><Input value={o.orderNumber} onChange={e => set('orderNumber', e.target.value)} /></Field><Field label="Order date"><Input type="date" value={o.orderDate} onChange={e => set('orderDate', e.target.value)} /></Field><Field label="Due date"><Input type="date" value={o.dueDate} onChange={e => set('dueDate', e.target.value)} /></Field><Field label="Payment status"><Select value={o.paymentStatus} onChange={e => set('paymentStatus', e.target.value)}><option>Unpaid</option><option>Part paid</option><option>Paid</option></Select></Field></div><div className="my-5 rounded-xl border"><div className="flex items-center justify-between border-b bg-muted/35 px-4 py-3"><p className="text-sm font-semibold">Items</p><Button type="button" variant="soft" className="min-h-8 px-2.5 text-xs" onClick={() => setO(x => ({ ...x, items: [...x.items, { productId: store.products[0]?.id || '', quantity: 1, unitPrice: store.products[0]?.retailPriceDozen || 0, costSnapshot: 0 }] }))}><Plus size={14} /> Add item</Button></div><div className="space-y-3 p-4">{o.items.map((item, idx) => <div className="grid items-end gap-3 sm:grid-cols-[1fr_100px_120px_30px]" key={idx}><Field label="Product"><Select value={item.productId} onChange={e => { const p = store.products.find(x => x.id === e.target.value); updateItem(idx, 'productId', e.target.value); updateItem(idx, 'unitPrice', p?.retailPriceDozen || 0); }} >{store.products.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</Select></Field><Field label="Qty"><Input type="number" min="1" value={item.quantity} onChange={e => updateItem(idx, 'quantity', Number(e.target.value))} /></Field><Field label="Price"><Input type="number" min="0" step=".01" value={item.unitPrice} onChange={e => updateItem(idx, 'unitPrice', Number(e.target.value))} /></Field><IconButton label="Remove item" onClick={() => setO(x => ({ ...x, items: x.items.filter((_, i) => i !== idx) }))}><Trash2 size={15} /></IconButton></div>)}</div></div><div className="grid gap-4 sm:grid-cols-4"><Field label="Discount"><Input type="number" min="0" value={o.discount} onChange={e => set('discount', Number(e.target.value))} /></Field><Field label="Delivery fee"><Input type="number" min="0" value={o.deliveryFee} onChange={e => set('deliveryFee', Number(e.target.value))} /></Field><Field label="Amount paid"><Input type="number" min="0" value={o.amountPaid} onChange={e => set('amountPaid', Number(e.target.value))} /></Field><Field label="Payment method"><Select value={o.paymentMethod} onChange={e => set('paymentMethod', e.target.value)}><option>Cash</option><option>Mobile money</option><option>Bank transfer</option></Select></Field></div><Field label="Notes"><textarea className="mt-4 min-h-16 w-full rounded-lg border bg-background p-3 text-sm outline-none focus:border-primary" value={o.notes} onChange={e => set('notes', e.target.value)} /></Field><div className="mt-5 flex items-center justify-between border-t pt-4"><div><span className="text-xs text-muted-foreground">Order total</span><p className="mono text-xl font-semibold">{money(total)}</p></div><div className="flex gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Save order</Button></div></div></form></Modal>;
}

function Expenses() {
  const { store, update } = useStore(); const [edit, setEdit] = useState<Expense | null>(null); const [location] = useLocation();
  const add = () => setEdit({ id: id('exp'), date: today(), category: 'Ingredients', description: '', amount: 0, supplier: '', relatedOrderId: '', notes: '' });
  useEffect(() => { if (location.includes('?new=1')) add(); }, [location]);
  const remove = (expense: Expense) => { if (window.confirm(`Delete ${expense.description || 'this expense'}?`)) update({ expenses: store.expenses.filter(x => x.id !== expense.id) }); };
  return <div><PageHeader eyebrow="Outgoings" title="Expenses" description="Keep the money leaving the bakery as visible as the money coming in." action={<Button onClick={add} data-testid="button-add-expense"><Plus size={17} /> Add expense</Button>} /><Card className="overflow-hidden">{store.expenses.length ? <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-muted/55 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3.5">Date</th><th>Description</th><th>Category</th><th>Supplier</th><th>Amount</th><th className="pr-5 text-right"> </th></tr></thead><tbody className="divide-y">{store.expenses.map(e => <tr key={e.id} className="hover:bg-muted/25"><td className="px-5 py-4 text-muted-foreground">{shortDate(e.date)}</td><td className="font-semibold">{e.description}</td><td><span className="rounded-full bg-muted px-2 py-1 text-xs">{e.category}</span></td><td>{e.supplier || '—'}</td><td className="mono">{money(e.amount)}</td><td className="pr-5 text-right"><IconButton label={`Edit ${e.description}`} onClick={() => setEdit(e)}><Pencil size={16} /></IconButton><IconButton label={`Delete ${e.description}`} onClick={() => remove(e)}><Trash2 size={16} /></IconButton></td></tr>)}</tbody></table></div> : <Empty icon={Wallet} title="No expenses recorded" detail="A clear expense trail makes your profit number trustworthy." action={<Button onClick={add}>Add expense</Button>} />}</Card>{edit && <ExpenseModal value={edit} onClose={() => setEdit(null)} onSave={e => { const exists = store.expenses.some(x => x.id === e.id); update({ expenses: exists ? store.expenses.map(x => x.id === e.id ? e : x) : [e, ...store.expenses] }); setEdit(null); }} />}</div>;
}
function ExpenseModal({ value, onClose, onSave }: { value: Expense; onClose: () => void; onSave: (v: Expense) => void }) { const [e, setE] = useState(value); const set = (k: keyof Expense, v: string | number) => setE(x => ({ ...x, [k]: v })); return <Modal title={value.description ? 'Edit expense' : 'New expense'} onClose={onClose}><form onSubmit={ev => { ev.preventDefault(); onSave(e); }} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Date"><Input type="date" value={e.date} onChange={x => set('date', x.target.value)} /></Field><Field label="Category"><Select value={e.category} onChange={x => set('category', x.target.value)}><option>Ingredients</option><option>Packaging</option><option>Utilities</option><option>Transport</option><option>Equipment</option><option>Other</option></Select></Field><Field label="Description"><Input required value={e.description} onChange={x => set('description', x.target.value)} /></Field><Field label="Amount"><Input required type="number" min="0" step=".01" value={e.amount} onChange={x => set('amount', Number(x.target.value))} /></Field><Field label="Supplier"><Input value={e.supplier} onChange={x => set('supplier', x.target.value)} /></Field></div><Field label="Notes"><textarea className="min-h-20 w-full rounded-lg border bg-background p-3 text-sm" value={e.notes} onChange={x => set('notes', x.target.value)} /></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Save expense</Button></div></form></Modal>; }

function Inventory() {
  const { store, update } = useStore(); const [edit, setEdit] = useState<InventoryTransaction | null>(null); const [location] = useLocation();
  const add = (type: string) => setEdit({ id: id('txn'), ingredientId: store.ingredients[0]?.id || '', type, quantity: 0, date: today(), note: '' });
  useEffect(() => { if (location.includes('?new=1')) add('receive'); }, [location]);
  const save = (t: InventoryTransaction) => { const ingredient = store.ingredients.find(i => i.id === t.ingredientId); if (!ingredient) return; const direction = t.type === 'waste' ? -1 : t.type === 'use' ? -1 : 1; update({ ingredients: store.ingredients.map(i => i.id === t.ingredientId ? { ...i, currentStock: Math.max(0, i.currentStock + direction * t.quantity) } : i), transactions: [t, ...store.transactions] }); setEdit(null); };
  return <div><PageHeader eyebrow="Pantry floor" title="Inventory" description="Know what is on hand before the first tray goes in." action={<div className="flex gap-2"><Button variant="soft" onClick={() => add('waste')}><ArrowDownRight size={16} /> Waste</Button><Button onClick={() => add('receive')}><Plus size={16} /> Receive stock</Button></div>} /><div className="mb-4 grid gap-3 sm:grid-cols-3"><Card className="p-4"><p className="text-xs text-muted-foreground">Stock value</p><p className="mono mt-2 text-2xl font-semibold">{money(store.ingredients.reduce((s, i) => s + (unitCost(i) || 0) * i.currentStock, 0))}</p></Card><Card className="p-4"><p className="text-xs text-muted-foreground">Tracked ingredients</p><p className="mono mt-2 text-2xl font-semibold">{store.ingredients.length}</p></Card><Card className="p-4"><p className="text-xs text-muted-foreground">Needs attention</p><p className="mono mt-2 text-2xl font-semibold text-primary">{store.ingredients.filter(i => i.minimumStock > 0 && i.currentStock <= i.minimumStock).length}</p></Card></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-muted/55 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3.5">Ingredient</th><th>On hand</th><th>Minimum</th><th>Unit cost</th><th>Stock value</th><th>Status</th><th className="pr-5 text-right">Adjust</th></tr></thead><tbody className="divide-y">{store.ingredients.map(i => { const low = i.minimumStock > 0 && i.currentStock <= i.minimumStock; return <tr key={i.id} className="hover:bg-muted/25"><td className="px-5 py-4 font-semibold">{i.name}</td><td className="mono">{i.currentStock.toLocaleString()} {i.unit}</td><td className="mono text-muted-foreground">{i.minimumStock || '—'}</td><td className="mono text-muted-foreground">{unitCost(i) ? money(unitCost(i)!) : '—'}</td><td className="mono">{unitCost(i) ? money(unitCost(i)! * i.currentStock) : '—'}</td><td>{low ? <span className="inline-flex items-center gap-1 text-xs font-semibold text-destructive"><CircleAlert size={14} /> Reorder</span> : <span className="text-xs text-primary">Healthy</span>}</td><td className="pr-5 text-right"><Button variant="ghost" className="min-h-8 px-2 text-xs" onClick={() => setEdit({ id: id('txn'), ingredientId: i.id, type: 'adjust', quantity: 0, date: today(), note: '' })}><RefreshCw size={14} /> Adjust</Button></td></tr>; })}</tbody></table></div></Card>{edit && <InventoryModal value={edit} ingredients={store.ingredients} onClose={() => setEdit(null)} onSave={save} />}</div>;
}
function InventoryModal({ value, ingredients, onClose, onSave }: { value: InventoryTransaction; ingredients: Ingredient[]; onClose: () => void; onSave: (v: InventoryTransaction) => void }) { const [t, setT] = useState(value); return <Modal title={value.type === 'waste' ? 'Record waste' : value.type === 'receive' ? 'Receive stock' : 'Adjust stock'} subtitle="This changes the on-hand number immediately." onClose={onClose}><form onSubmit={e => { e.preventDefault(); onSave(t); }} className="space-y-4"><Field label="Ingredient"><Select value={t.ingredientId} onChange={e => setT({ ...t, ingredientId: e.target.value })}>{ingredients.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}</Select></Field><Field label={t.type === 'adjust' ? 'Adjustment quantity' : 'Quantity'} hint={t.type === 'adjust' ? 'For an adjustment, use the amount to add or remove.' : undefined}><Input required type="number" min="0" step=".01" value={t.quantity} onChange={e => setT({ ...t, quantity: Number(e.target.value) })} /></Field><Field label="Date"><Input type="date" value={t.date} onChange={e => setT({ ...t, date: e.target.value })} /></Field><Field label="Note"><Input value={t.note} onChange={e => setT({ ...t, note: e.target.value })} placeholder="Optional context" /></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Save adjustment</Button></div></form></Modal>; }

function Reports() {
  const { store } = useStore(); const [period, setPeriod] = useState('Monthly'); const revenue = store.orders.reduce((s, o) => s + o.items.reduce((a, i) => a + i.quantity * i.unitPrice, 0) - o.discount + o.deliveryFee, 0); const costs = store.orders.reduce((s, o) => s + o.items.reduce((a, i) => a + i.quantity * i.costSnapshot, 0), 0); const productSales = store.products.map(p => ({ ...p, units: store.orders.reduce((s, o) => s + o.items.filter(i => i.productId === p.id).reduce((a, i) => a + i.quantity, 0), 0) })).sort((a, b) => b.units - a.units);
  const download = (filename: string, content: string) => { const blob = new Blob([content], { type: 'text/csv' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url); };
  return <div><PageHeader eyebrow="Numbers with context" title="Reports" description="A weekly rhythm for seeing what is working and what to change." action={<Button variant="soft" onClick={() => download('little-bliss-orders.csv', `order,customer,total,status\n${store.orders.map(o => `${o.orderNumber},${o.customerName},${o.items.reduce((a, i) => a + i.quantity * i.unitPrice, 0)},${o.paymentStatus}`).join('\n')}`)}><Download size={16} /> Export CSV</Button>} /><div className="mb-5 flex items-center gap-1 rounded-lg border bg-card p-1 w-fit">{['Daily', 'Weekly', 'Monthly'].map(x => <button key={x} data-testid={`button-period-${x.toLowerCase()}`} onClick={() => setPeriod(x)} className={cx('rounded-md px-4 py-2 text-xs font-semibold', period === x ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted')}>{x}</button>)}</div><div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><Card className="p-5"><div className="flex items-start justify-between"><div><p className="text-xs text-muted-foreground">{period} revenue</p><p className="mono mt-2 text-3xl font-semibold">{money(revenue)}</p></div><span className="rounded-full bg-secondary px-2.5 py-1 text-xs font-semibold text-secondary-foreground"><ArrowUpRight size={13} className="mr-1 inline" />12.4%</span></div><div className="mt-8 flex h-44 items-end gap-2 border-b border-l px-3 pb-0 pt-4">{[42, 55, 48, 70, 62, 86, 74, 92, 68, 80, 96, 78].map((h, i) => <div key={i} className="group flex h-full flex-1 items-end"><div className={cx('w-full rounded-t-sm', i === 11 ? 'bg-primary' : 'bg-secondary/70 group-hover:bg-primary/60')} style={{ height: `${h}%` }} /></div>)}</div><div className="mt-2 flex justify-between pl-3 text-[10px] text-muted-foreground"><span>01 Aug</span><span>12 Aug</span><span>24 Aug</span><span>Today</span></div></Card><Card className="p-5"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-semibold">Profitability snapshot</h2><p className="text-xs text-muted-foreground">Across all saved orders</p></div><TrendingUp size={18} className="text-primary" /></div><div className="space-y-5"><ReportLine label="Revenue" value={revenue} total={Math.max(revenue, 1)} color="bg-primary" /><ReportLine label="Estimated production" value={costs} total={Math.max(revenue, 1)} color="bg-accent" /><ReportLine label="Recorded expenses" value={store.expenses.reduce((s, e) => s + e.amount, 0)} total={Math.max(revenue, 1)} color="bg-sidebar" /></div><div className="mt-6 border-t pt-4"><div className="flex justify-between"><span className="text-sm text-muted-foreground">Expected profit</span><span className="mono font-semibold text-primary">{money(revenue - costs - store.expenses.reduce((s, e) => s + e.amount, 0))}</span></div></div></Card></div><Card className="mt-5 overflow-hidden"><div className="flex items-center justify-between border-b px-5 py-4"><div><h2 className="font-semibold">Product profitability</h2><p className="text-xs text-muted-foreground">Retail price less recipe cost, per dozen</p></div><Button variant="ghost" onClick={() => download('little-bliss-product-profitability.csv', `product,price,cost,profit,margin\n${productSales.map(p => `${p.name},${p.retailPriceDozen},0,${p.retailPriceDozen},0`).join('\n')}`)}><Download size={15} /> CSV</Button></div><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="bg-muted/55 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3">Product</th><th>Units sold</th><th>Revenue</th><th>Price / dozen</th><th>Signal</th></tr></thead><tbody className="divide-y">{productSales.map(p => <tr key={p.id}><td className="px-5 py-4 font-semibold">{p.name}</td><td className="mono">{p.units}</td><td className="mono">{money(p.units * p.retailPriceDozen)}</td><td className="mono">{money(p.retailPriceDozen)}</td><td><span className={cx('text-xs font-semibold', p.units ? 'text-primary' : 'text-muted-foreground')}>{p.units ? 'Selling' : 'No sales yet'}</span></td></tr>)}</tbody></table></div></Card></div>;
}
function ReportLine({ label, value, total, color }: { label: string; value: number; total: number; color: string }) { return <div><div className="mb-1.5 flex justify-between text-xs"><span>{label}</span><span className="mono">{money(value)}</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className={cx('h-full rounded-full', color)} style={{ width: `${Math.min(100, value / total * 100)}%` }} /></div></div>; }

function Budget() {
  const { store, update } = useStore(); const [edit, setEdit] = useState<BudgetAllocation | null>(null); const received = store.orders.reduce((s, o) => s + o.amountPaid, 0); const expenses = store.expenses.reduce((s, e) => s + e.amount, 0); const available = received - expenses; const allocated = store.allocations.reduce((s, a) => s + (a.mode === 'percent' ? available * a.value / 100 : a.value), 0);
  return <div><PageHeader eyebrow="Cash plan" title="Budget" description="Give every pula a job, without losing sight of what is available." action={<Button onClick={() => setEdit({ id: id('alloc'), name: '', mode: 'percent', value: 0 })}><Plus size={17} /> Add allocation</Button>} /><div className="grid gap-4 sm:grid-cols-3"><Card className="bg-sidebar p-5 text-sidebar-foreground"><p className="text-xs opacity-65">Available cash</p><p className="mono mt-3 text-3xl font-semibold">{money(available)}</p><p className="mt-2 text-xs opacity-65">received less actual expenses</p></Card><Card className="p-5"><p className="text-xs text-muted-foreground">Allocated</p><p className="mono mt-3 text-3xl font-semibold">{money(allocated)}</p><p className="mt-2 text-xs text-muted-foreground">{allocated > available ? 'Over your available cash' : 'planned across allocations'}</p></Card><Card className="p-5"><p className="text-xs text-muted-foreground">Remaining</p><p className={cx('mono mt-3 text-3xl font-semibold', available - allocated < 0 && 'text-destructive')}>{money(available - allocated)}</p><p className="mt-2 text-xs text-muted-foreground">{available - allocated < 0 ? 'Review your plan' : 'still unassigned'}</p></Card></div><Card className="mt-5 overflow-hidden"><div className="border-b px-5 py-4"><h2 className="font-semibold">Allocation plan</h2><p className="mt-0.5 text-xs text-muted-foreground">Percent allocations flex with your cash; fixed allocations stay fixed.</p></div>{store.allocations.length ? <div className="divide-y">{store.allocations.map(a => { const amount = a.mode === 'percent' ? available * a.value / 100 : a.value; return <div key={a.id} className="flex items-center gap-4 px-5 py-4"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-secondary text-secondary-foreground"><Wallet size={16} /></div><div className="min-w-0 flex-1"><p className="font-semibold">{a.name}</p><p className="text-xs text-muted-foreground">{a.mode === 'percent' ? `${a.value}% of available cash` : 'Fixed amount'}</p></div><p className="mono text-sm font-semibold">{money(amount)}</p><IconButton label={`Edit ${a.name}`} onClick={() => setEdit(a)}><Pencil size={16} /></IconButton><IconButton label={`Delete ${a.name}`} onClick={() => update({ allocations: store.allocations.filter(x => x.id !== a.id) })}><Trash2 size={16} /></IconButton></div>; })}</div> : <Empty icon={Wallet} title="No allocations yet" detail="Add a simple cash plan to give the month a shape." />}</Card>{edit && <BudgetModal value={edit} onClose={() => setEdit(null)} onSave={a => { const exists = store.allocations.some(x => x.id === a.id); update({ allocations: exists ? store.allocations.map(x => x.id === a.id ? a : x) : [...store.allocations, a] }); setEdit(null); }} />}</div>;
}
function BudgetModal({ value, onClose, onSave }: { value: BudgetAllocation; onClose: () => void; onSave: (v: BudgetAllocation) => void }) { const [a, setA] = useState(value); return <Modal title={value.name ? 'Edit allocation' : 'New allocation'} onClose={onClose}><form onSubmit={e => { e.preventDefault(); onSave(a); }} className="space-y-4"><Field label="Name"><Input required value={a.name} onChange={e => setA({ ...a, name: e.target.value })} placeholder="e.g. Ingredients" /></Field><Field label="Mode"><Select value={a.mode} onChange={e => setA({ ...a, mode: e.target.value })}><option value="percent">Percent of available</option><option value="fixed">Fixed amount</option></Select></Field><Field label={a.mode === 'percent' ? 'Percentage' : 'Amount'}><Input type="number" min="0" step=".01" value={a.value} onChange={e => setA({ ...a, value: Number(e.target.value) })} /></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Save allocation</Button></div></form></Modal>; }

function SettingsPage() {
  const { store, update } = useStore(); const [s, setS] = useState(store.settings); const [saved, setSaved] = useState(false); const file = useRef<HTMLInputElement>(null);
  useEffect(() => setS(store.settings), [store.settings]);
  const save = (e: FormEvent) => { e.preventDefault(); update({ settings: s }); setSaved(true); window.setTimeout(() => setSaved(false), 1800); };
  const backup = () => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify(store, null, 2)], { type: 'application/json' })); a.download = 'little-bliss-backup.json'; a.click(); };
  const importBackup = (event: React.ChangeEvent<HTMLInputElement>) => { const f = event.target.files?.[0]; if (!f) return; const reader = new FileReader(); reader.onload = () => { try { const parsed = JSON.parse(String(reader.result)) as Store; if (parsed.products && parsed.ingredients && parsed.settings) update(parsed); } catch { window.alert('That backup could not be read.'); } }; reader.readAsText(f); };
  return <div><PageHeader eyebrow="Your bakery" title="Settings" description="A few details that make this desk feel like yours." /><div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><Card className="p-5 sm:p-6"><div className="mb-5"><h2 className="font-semibold">Business information</h2><p className="mt-1 text-xs text-muted-foreground">Shown in your local workspace and exports.</p></div><form onSubmit={save} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Bakery name"><Input value={s.bakeryName} onChange={e => setS({ ...s, bakeryName: e.target.value })} /></Field><Field label="Phone"><Input value={s.phone} onChange={e => setS({ ...s, phone: e.target.value })} /></Field><Field label="Email"><Input type="email" value={s.email} onChange={e => setS({ ...s, email: e.target.value })} /></Field><Field label="Currency"><Select value={s.currency} onChange={e => setS({ ...s, currency: e.target.value })}><option value="E">E · Eswatini Lilangeni</option></Select></Field></div><Field label="Address"><Input value={s.address} onChange={e => setS({ ...s, address: e.target.value })} /></Field><div className="flex items-center justify-between border-t pt-4"><span className={cx('text-xs font-semibold text-primary transition-opacity', !saved && 'opacity-0')}><Check size={14} className="mr-1 inline" /> Saved just now</span><Button type="submit" data-testid="button-save-settings">Save changes</Button></div></form></Card><div className="space-y-5"><Card className="p-5 sm:p-6"><h2 className="font-semibold">Appearance</h2><p className="mt-1 text-xs text-muted-foreground">Choose the mood for early mornings.</p><div className="mt-4 grid grid-cols-2 gap-2"><button data-testid="button-theme-light" onClick={() => update({ settings: { ...store.settings, theme: 'light' } })} className={cx('rounded-lg border p-3 text-left', s.theme === 'light' ? 'border-primary bg-primary/5' : 'hover:bg-muted')}><div className="mb-2 h-8 rounded bg-[#f8f4eb] ring-1 ring-border" /><p className="text-xs font-semibold">Morning light</p></button><button data-testid="button-theme-dark" onClick={() => update({ settings: { ...store.settings, theme: 'dark' } })} className={cx('rounded-lg border p-3 text-left', s.theme === 'dark' ? 'border-primary bg-primary/5' : 'hover:bg-muted')}><div className="mb-2 h-8 rounded bg-[#291b23] ring-1 ring-border" /><p className="text-xs font-semibold">After hours</p></button></div></Card><Card className="p-5 sm:p-6"><h2 className="font-semibold">Your data</h2><p className="mt-1 text-xs text-muted-foreground">Everything stays in this browser on this device.</p><div className="mt-4 space-y-2"><Button variant="soft" className="w-full justify-start" onClick={backup}><Download size={16} /> Export JSON backup</Button><Button variant="ghost" className="w-full justify-start border" onClick={() => file.current?.click()}><Upload size={16} /> Import JSON backup</Button><input ref={file} type="file" accept=".json" className="hidden" onChange={importBackup} /><Button variant="ghost" className="w-full justify-start border text-destructive hover:bg-destructive/10" onClick={() => { if (window.confirm('Reset all local data to the original demo?')) { resetStore(); window.location.reload(); } }}><RefreshCw size={16} /> Reset demo data</Button></div><div className="mt-4 rounded-lg bg-accent/25 p-3 text-xs leading-relaxed text-muted-foreground"><CircleAlert size={14} className="mr-1 inline text-primary" /> Device storage reminder: clear browser data or private browsing can remove your bakery records. Export a backup occasionally.</div></Card></div></div></div>;
}
function NotFound() { return <div className="flex min-h-[60vh] flex-col items-center justify-center text-center"><span className="rounded-full bg-secondary p-4"><FileText size={24} /></span><h1 className="display mt-5 text-3xl">That shelf is empty.</h1><p className="mt-2 text-sm text-muted-foreground">This page is not part of the bakery desk.</p><Link href="/" className="mt-5 text-sm font-semibold text-primary hover:underline">Return to overview</Link></div>; }

function Router() { return <Switch><Route path="/" component={Dashboard} /><Route path="/products" component={Products} /><Route path="/ingredients" component={Ingredients} /><Route path="/recipes" component={Recipes} /><Route path="/orders" component={Orders} /><Route path="/expenses" component={Expenses} /><Route path="/inventory" component={Inventory} /><Route path="/reports" component={Reports} /><Route path="/budget" component={Budget} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch>; }
export default function App() {
  const [store, setStore] = useState<Store>(() => loadStore());
  const update = (patch: Partial<Store>) => setStore(current => { const next = { ...current, ...patch }; saveStore(next); return next; });
  useEffect(() => { document.documentElement.classList.toggle('dark', store.settings.theme === 'dark'); }, [store.settings.theme]);
  return <StoreContext.Provider value={{ store, update }}><AppShell><Router /></AppShell></StoreContext.Provider>;
}